const fs = require('fs');
const zlib = require('zlib');
const path = '/workspace/testbed/docs/customer_report.docx';
const buf = fs.readFileSync(path);

// Manual ZIP parsing to extract word/document.xml
let offset = 0;
while (offset < buf.length - 4) {
  const sig = buf.readUInt32LE(offset);
  if (sig !== 0x04034b50) break; // local file header
  const compMethod = buf.readUInt16LE(offset + 8);
  const fnameLen = buf.readUInt16LE(offset + 26);
  const extraLen = buf.readUInt16LE(offset + 28);
  const compSize = buf.readUInt32LE(offset + 18);
  const fname = buf.slice(offset + 30, offset + 30 + fnameLen).toString('utf8');
  const dataStart = offset + 30 + fnameLen + extraLen;

  if (fname === 'word/document.xml') {
    let data;
    if (compMethod === 0) {
      data = buf.slice(dataStart, dataStart + compSize);
    } else {
      data = zlib.inflateRawSync(buf.slice(dataStart, dataStart + compSize));
    }
    // Parse XML and extract text
    const xml = data.toString('utf8');
    // Extract text between <w:t> tags
    const texts = [];
    let currentPara = [];
    const parts = xml.split(/(<[^>]+>)/);
    let inT = false;
    for (const part of parts) {
      if (part.match(/<w:t[ >]/)) { inT = true; continue; }
      if (part === '</w:t>') { inT = false; continue; }
      if (part.match(/<\\/w:p[ >]/) || part === '</w:p>') {
        if (currentPara.length) texts.push(currentPara.join(''));
        currentPara = [];
        continue;
      }
      if (inT && !part.startsWith('<')) currentPara.push(part);
    }
    if (currentPara.length) texts.push(currentPara.join(''));
    console.log(texts.join('\\n\\n'));
    process.exit(0);
  }
  offset = dataStart + compSize;
}
