const fs = require('fs');
const zlib = require('zlib');
const PDFDocument = require('pdfkit');

// --- Extract text from .docx ---
const docxPath = '/workspace/testbed/docs/customer_report.docx';
const buf = fs.readFileSync(docxPath);

let xmlData = null;
let offset = 0;
while (offset < buf.length - 4) {
  const sig = buf.readUInt32LE(offset);
  if (sig !== 0x04034b50) break;
  const compMethod = buf.readUInt16LE(offset + 8);
  const fnameLen = buf.readUInt16LE(offset + 26);
  const extraLen = buf.readUInt16LE(offset + 28);
  const compSize = buf.readUInt32LE(offset + 18);
  const fname = buf.slice(offset + 30, offset + 30 + fnameLen).toString('utf8');
  const dataStart = offset + 30 + fnameLen + extraLen;
  if (fname === 'word/document.xml') {
    xmlData = compMethod === 0
      ? buf.slice(dataStart, dataStart + compSize)
      : zlib.inflateRawSync(buf.slice(dataStart, dataStart + compSize));
    break;
  }
  offset = dataStart + compSize;
}

const xml = xmlData.toString('utf8');

// Parse paragraphs with bold detection
const paragraphs = [];
// Split by <w:p ...>...</w:p>
const pRegex = /<w:p[ >]([\s\S]*?)<\/w:p>/g;
let pMatch;
while ((pMatch = pRegex.exec(xml)) !== null) {
  const pContent = pMatch[1];
  const runs = [];
  // Check for heading style
  let isHeading = false;
  const styleMatch = pContent.match(/<w:pStyle w:val=\"([^\"]*)\"/);
  if (styleMatch && styleMatch[1].startsWith('Heading')) isHeading = true;

  // Extract runs
  const rRegex = /<w:r[ >]([\s\S]*?)<\/w:r>/g;
  let rMatch;
  while ((rMatch = rRegex.exec(pContent)) !== null) {
    const rContent = rMatch[1];
    const isBold = /<w:b[ \/]/.test(rContent) || /<w:b>/.test(rContent);
    const tMatch = rContent.match(/<w:t[^>]*>([^<]*)<\/w:t>/);
    if (tMatch) {
      runs.push({ text: tMatch[1], bold: isBold || isHeading });
    }
  }
  if (runs.length > 0) {
    paragraphs.push({ runs, isHeading });
  }
}

// --- Generate PDF ---
const doc = new PDFDocument({ margin: 50 });
const pdfPath = '/workspace/testbed/docs/customer_report.pdf';
const stream = fs.createWriteStream(pdfPath);
doc.pipe(stream);

for (const para of paragraphs) {
  if (para.isHeading) {
    doc.fontSize(16).font('Helvetica-Bold');
    const text = para.runs.map(r => r.text).join('');
    doc.text(text, { paragraphGap: 8 });
    doc.moveDown(0.3);
  } else {
    doc.fontSize(10);
    for (let i = 0; i < para.runs.length; i++) {
      const r = para.runs[i];
      const font = r.bold ? 'Helvetica-Bold' : 'Helvetica';
      const isLast = (i === para.runs.length - 1);
      doc.font(font).text(r.text, { continued: !isLast });
    }
    doc.moveDown(0.2);
  }
}

doc.end();
stream.on('finish', () => {
  const stats = fs.statSync(pdfPath);
  console.log('PDF created:', pdfPath);
  console.log('Size:', stats.size, 'bytes');
});
" 2>&1
